import { beforeEach, describe, expect, it, vi } from "vitest"
import type { ChatHistory } from "@/store/option"
import { saveMessageOnError } from "../index"

const mocks = vi.hoisted(() => ({
  fallbackSetHistory: vi.fn(),
  saveMessage: vi.fn(async () => undefined),
  getLastChatHistory: vi.fn(async () => ({ id: "last-message-id" })),
  saveHistory: vi.fn(async () => ({ id: "new-history-id" })),
  updateMessage: vi.fn(async () => undefined),
  setLastUsedChatModel: vi.fn(async () => undefined),
  setLastUsedChatSystemPrompt: vi.fn(async () => undefined),
  updateChatHistoryCreatedAt: vi.fn(async () => undefined),
  generateTitle: vi.fn(async () => "Generated title"),
  runTransaction: vi.fn(
    async (
      signal: AbortSignal | undefined,
      operation: () => Promise<unknown>,
      shouldAbort?: () => boolean
    ) => {
      if (signal?.aborted && (shouldAbort?.() ?? true)) {
        const error = new Error("Request scope changed")
        error.name = "AbortError"
        throw error
      }
      return operation()
    }
  ),
  updatePageTitle: vi.fn(),
  buildAssistantErrorContent: vi.fn((_botMessage: string, error: unknown) =>
    error instanceof Error ? `ERR: ${error.message}` : "ERR"
  )
}))

vi.mock("@/store/option", () => ({
  useStoreMessageOption: {
    getState: () => ({
      setHistory: mocks.fallbackSetHistory
    })
  }
}))

vi.mock("@/db/dexie/helpers", () => ({
  getLastChatHistory: mocks.getLastChatHistory,
  saveHistory: mocks.saveHistory,
  saveMessage: mocks.saveMessage,
  updateMessage: mocks.updateMessage,
  updateLastUsedModel: mocks.setLastUsedChatModel,
  updateLastUsedPrompt: mocks.setLastUsedChatSystemPrompt,
  updateChatHistoryCreatedAt: mocks.updateChatHistoryCreatedAt
}))

vi.mock("@/services/title", () => ({
  generateTitle: mocks.generateTitle
}))

vi.mock("@/db/dexie/chat-persistence-transaction", () => ({
  runChatPersistenceTransaction: mocks.runTransaction
}))

vi.mock("@/utils/update-page-title", () => ({
  updatePageTitle: mocks.updatePageTitle
}))

vi.mock("@/utils/chat-error-message", () => ({
  buildAssistantErrorContent: mocks.buildAssistantErrorContent
}))

describe("saveMessageOnError", () => {
  beforeEach(() => {
    mocks.fallbackSetHistory.mockClear()
    mocks.saveMessage.mockClear()
    mocks.getLastChatHistory.mockClear()
    mocks.saveHistory.mockClear()
    mocks.updateMessage.mockClear()
    mocks.setLastUsedChatModel.mockClear()
    mocks.setLastUsedChatSystemPrompt.mockClear()
    mocks.updateChatHistoryCreatedAt.mockClear()
    mocks.generateTitle.mockClear()
    mocks.runTransaction.mockClear()
    mocks.updatePageTitle.mockClear()
    mocks.buildAssistantErrorContent.mockClear()
  })

  it("persists an acknowledged user beside an interrupted assistant without changing local IDs", async () => {
    await saveMessageOnError({
      e: new Error("provider failed"), history: [], setHistory: vi.fn(), image: "",
      userMessage: "Question", botMessage: "Partial", historyId: "history-1",
      selectedModel: "test", setHistoryId: vi.fn(), isRegenerating: false,
      userMessageId: "local-user", userServerMessageId: "server-user", assistantMessageId: "local-assistant"
    })
    expect(mocks.saveMessage).toHaveBeenCalledWith(expect.objectContaining({
      id: "local-user", serverMessageId: "server-user", role: "user", content: "Question"
    }))
    expect(mocks.saveMessage).toHaveBeenCalledWith(expect.objectContaining({
      id: "local-assistant", role: "assistant"
    }))
  })

  it("falls back to store setter when setHistory is not callable", async () => {
    const history: ChatHistory = [
      {
        role: "assistant",
        content: "Earlier assistant response"
      }
    ]

    await expect(
      saveMessageOnError({
        e: new Error("provider failed"),
        history,
        setHistory: null as unknown as (history: ChatHistory) => void,
        image: "",
        userMessage: "Hi there",
        botMessage: "",
        historyId: "history-1",
        selectedModel: "kimi-k2",
        setHistoryId: vi.fn(),
        isRegenerating: false
      })
    ).resolves.toBe("history-1")

    expect(mocks.fallbackSetHistory).toHaveBeenCalledTimes(1)
    expect(mocks.fallbackSetHistory).toHaveBeenCalledWith([
      ...history,
      {
        role: "user",
        content: "Hi there",
        image: ""
      },
      {
        role: "assistant",
        content: "ERR: provider failed"
      }
    ])
  })

  it("uses a local fallback title when provider title generation fails during error recovery", async () => {
    const setHistory = vi.fn()
    const setHistoryId = vi.fn()
    mocks.generateTitle.mockRejectedValueOnce(new Error("missing provider key"))

    await expect(
      saveMessageOnError({
        e: new Error("provider failed"),
        history: [],
        setHistory,
        image: "",
        userMessage: "Please summarize this cockpit error recovery path",
        botMessage: "",
        historyId: null,
        selectedModel: "openai/gpt-4o",
        setHistoryId,
        isRegenerating: false
      })
    ).resolves.toBe("new-history-id")

    expect(mocks.saveHistory).toHaveBeenCalledWith(
      "Please summarize this cockpit error recovery path",
      false,
      "web-ui"
    )
    expect(mocks.updatePageTitle).toHaveBeenCalledWith(
      "Please summarize this cockpit error recovery path"
    )
    expect(setHistoryId).toHaveBeenCalledWith("new-history-id")
  })

  it("persists user and assistant metadata extras when saving error records", async () => {
    await expect(
      saveMessageOnError({
        e: new Error("provider failed"),
        history: [],
        setHistory: vi.fn(),
        image: "",
        userMessage: "Submit OpenUI action",
        botMessage: "",
        historyId: "history-1",
        selectedModel: "openai/gpt-4o",
        setHistoryId: vi.fn(),
        isRegenerating: false,
        userMessageId: "user-1",
        assistantMessageId: "assistant-1",
        userMetadataExtra: {
          dynamic_ui_action: { actionId: "survey" }
        },
        assistantMetadataExtra: {
          dynamic_ui: {
            renderer: "openui",
            version: "v1",
            source: "root = <Card />"
          }
        }
      } as any)
    ).resolves.toBe("history-1")

    expect(mocks.saveMessage).toHaveBeenCalledWith(
      expect.objectContaining({
        id: "user-1",
        role: "user",
        metadataExtra: {
          dynamic_ui_action: { actionId: "survey" }
        }
      })
    )
    expect(mocks.saveMessage).toHaveBeenCalledWith(
      expect.objectContaining({
        id: "assistant-1",
        role: "assistant",
        metadataExtra: {
          dynamic_ui: {
            renderer: "openui",
            version: "v1",
            source: "root = <Card />"
          }
        }
      })
    )
  })

  it("writes nothing when an error save starts after a scope-only abort", async () => {
    const controller = new AbortController()
    controller.abort()
    const setHistory = vi.fn()

    await expect(
      saveMessageOnError({
        e: new Error("provider failed"),
        history: [],
        setHistory,
        image: "",
        userMessage: "Scoped question",
        botMessage: "partial",
        historyId: "history-1",
        selectedModel: "model-1",
        setHistoryId: vi.fn(),
        isRegenerating: false,
        scopeSignal: controller.signal,
        scopeInvalidatedSignal: controller.signal,
        shouldAbortForScopeChange: () => true
      } as any)
    ).rejects.toMatchObject({ name: "AbortError" })

    expect(mocks.saveMessage).not.toHaveBeenCalled()
    expect(setHistory).not.toHaveBeenCalled()
  })

  it("defers scoped Compare metadata while preserving error messages", async () => {
    const controller = new AbortController()
    const scopeInvalidatedController = new AbortController()

    await expect(
      saveMessageOnError({
        e: new Error("provider failed"),
        history: [],
        setHistory: vi.fn(),
        image: "",
        userMessage: "Scoped question",
        botMessage: "",
        historyId: "history-1",
        selectedModel: "model-1",
        setHistoryId: vi.fn(),
        isRegenerating: false,
        scopeSignal: controller.signal,
        scopeInvalidatedSignal: scopeInvalidatedController.signal,
        deferHistoryMetadata: true,
        prompt_id: "prompt-1"
      } as any)
    ).resolves.toBe("history-1")

    expect(mocks.saveMessage).toHaveBeenCalledTimes(2)
    expect(mocks.setLastUsedChatModel).not.toHaveBeenCalled()
    expect(mocks.setLastUsedChatSystemPrompt).not.toHaveBeenCalled()
  })

  it("still persists a manual-stop partial when the scope lease signal is aborted", async () => {
    const controller = new AbortController()
    const scopeInvalidatedController = new AbortController()
    controller.abort()

    await expect(
      saveMessageOnError({
        e: Object.assign(new Error("Request cancelled"), { name: "AbortError" }),
        history: [],
        setHistory: vi.fn(),
        image: "",
        userMessage: "Scoped question",
        botMessage: "partial answer",
        historyId: "history-1",
        selectedModel: "model-1",
        setHistoryId: vi.fn(),
        isRegenerating: false,
        scopeSignal: controller.signal,
        scopeInvalidatedSignal: scopeInvalidatedController.signal,
        shouldAbortForScopeChange: () => false
      } as any)
    ).resolves.toBe("history-1")

    expect(mocks.runTransaction).toHaveBeenCalledWith(
      scopeInvalidatedController.signal,
      expect.any(Function),
      expect.any(Function)
    )
    expect(mocks.saveMessage).toHaveBeenCalledWith(
      expect.objectContaining({ role: "assistant", content: "ERR: Request cancelled" })
    )
  })

  it("does not turn a scoped title 412 into an unscoped fallback history", async () => {
    const scopeInvalidatedController = new AbortController()
    const scopeChangedError = Object.assign(new Error("scope changed"), {
      status: 412,
      details: { code: "request_config_scope_changed" }
    })
    const requestScope = Object.freeze({
      config: Object.freeze({
        serverUrl: "https://scope.example",
        authMode: "multi-user" as const
      }),
      userId: 7
    })
    mocks.generateTitle.mockRejectedValueOnce(scopeChangedError)

    await expect(
      saveMessageOnError({
        e: new Error("provider failed"),
        history: [],
        setHistory: vi.fn(),
        image: "",
        userMessage: "Scoped question",
        botMessage: "partial answer",
        historyId: null,
        selectedModel: "model-1",
        setHistoryId: vi.fn(),
        isRegenerating: false,
        scopeSignal: new AbortController().signal,
        scopeInvalidatedSignal: scopeInvalidatedController.signal,
        requestScope,
        shouldAbortForScopeChange: () => false
      } as any)
    ).rejects.toBe(scopeChangedError)

    expect(mocks.generateTitle).toHaveBeenCalledWith(
      "model-1",
      "Scoped question",
      "Scoped question",
      { requestScope, signal: expect.any(AbortSignal) }
    )
    expect(mocks.saveHistory).not.toHaveBeenCalled()
    expect(mocks.saveMessage).not.toHaveBeenCalled()
  })

  it("cancels scoped title generation when the account scope changes", async () => {
    const controller = new AbortController()
    const requestScope = Object.freeze({
      config: Object.freeze({
        serverUrl: "https://scope.example",
        authMode: "multi-user" as const
      }),
      userId: 7
    })
    mocks.generateTitle.mockImplementationOnce(
      async (
        _model: string,
        _message: string,
        _fallback: string,
        options?: { signal?: AbortSignal }
      ) => await new Promise<string>((_resolve, reject) => {
        options?.signal?.addEventListener("abort", () => {
          reject(new DOMException("Aborted", "AbortError"))
        }, { once: true })
      })
    )

    const pending = saveMessageOnError({
      e: new Error("provider failed"),
      history: [],
      setHistory: vi.fn(),
      image: "",
      userMessage: "Scoped question",
      botMessage: "partial answer",
      historyId: null,
      selectedModel: "model-1",
      setHistoryId: vi.fn(),
      isRegenerating: false,
      scopeSignal: controller.signal,
      scopeInvalidatedSignal: controller.signal,
      requestScope,
      shouldAbortForScopeChange: () => controller.signal.aborted
    })
    await vi.waitFor(() => expect(mocks.generateTitle).toHaveBeenCalledOnce())

    controller.abort()

    await expect(pending).rejects.toMatchObject({ name: "AbortError" })
    expect(mocks.saveHistory).not.toHaveBeenCalled()
    expect(mocks.saveMessage).not.toHaveBeenCalled()
  })
})

import { beforeEach, describe, expect, it, vi } from "vitest"

const mocks = vi.hoisted(() => ({
  events: [] as string[],
  generateTitle: vi.fn(async () => {
    mocks.events.push("title")
    return "Generated title"
  }),
  getLastChatHistory: vi.fn(async () => ({ id: "last-assistant" })),
  addFileToSession: vi.fn(async (_historyId: string, file: { id: string }) => {
    mocks.events.push(`save:file:${file.id}`)
  }),
  runTransaction: vi.fn(
    async (signal: AbortSignal | undefined, operation: () => Promise<unknown>) => {
      if (signal?.aborted) {
        const error = new Error("Request scope changed")
        error.name = "AbortError"
        throw error
      }
      mocks.events.push("transaction:start")
      const result = await operation()
      mocks.events.push("transaction:commit")
      return result
    }
  ),
  saveHistory: vi.fn(async () => {
    mocks.events.push("saveHistory")
    return { id: "new-history" }
  }),
  saveMessage: vi.fn(async (message: { role: string }) => {
    mocks.events.push(`save:${message.role}`)
  }),
  setLastUsedModel: vi.fn(async () => {
    mocks.events.push("save:model")
  }),
  setLastUsedPrompt: vi.fn(async () => {
    mocks.events.push("save:prompt")
  }),
  updateCreatedAt: vi.fn(async () => {
    mocks.events.push("save:createdAt")
  }),
  updateMessage: vi.fn(async () => undefined),
  updatePageTitle: vi.fn(() => {
    mocks.events.push("pageTitle")
  })
}))

vi.mock("@/db/dexie/helpers", () => ({
  addFileToSession: mocks.addFileToSession,
  getLastChatHistory: mocks.getLastChatHistory,
  saveHistory: mocks.saveHistory,
  saveMessage: mocks.saveMessage,
  updateMessage: mocks.updateMessage,
  updateLastUsedModel: mocks.setLastUsedModel,
  updateLastUsedPrompt: mocks.setLastUsedPrompt,
  updateChatHistoryCreatedAt: mocks.updateCreatedAt
}))

vi.mock("@/db/dexie/chat-persistence-transaction", () => ({
  runChatPersistenceTransaction: mocks.runTransaction
}))

vi.mock("@/services/title", () => ({ generateTitle: mocks.generateTitle }))
vi.mock("@/utils/update-page-title", () => ({
  updatePageTitle: mocks.updatePageTitle
}))
vi.mock("@/store/option", () => ({
  useStoreMessageOption: { getState: () => ({ setHistory: vi.fn() }) }
}))
vi.mock("@/utils/chat-error-message", () => ({
  buildAssistantErrorContent: vi.fn()
}))

import { saveMessageOnSuccess } from "../index"

const requestScope = Object.freeze({
  config: Object.freeze({
    serverUrl: "https://scope.example",
    authMode: "multi-user" as const
  }),
  userId: 7
})

const payload = (overrides: Record<string, unknown> = {}) => ({
  historyId: "history-1",
  setHistoryId: vi.fn(),
  isRegenerate: false,
  selectedModel: "model-1",
  message: "question",
  image: "",
  fullText: "answer",
  source: [],
  modelId: "model-1",
  userMessageId: "user-1",
  assistantMessageId: "assistant-1",
  ...overrides
})

describe("saveMessageOnSuccess request scope", () => {
  beforeEach(() => {
    vi.clearAllMocks()
    mocks.events.length = 0
  })

  it("retains the server acknowledgement on each matching locally persisted row", async () => {
    await saveMessageOnSuccess(payload({ assistantServerMessageId: "server-assistant-1", userServerMessageId: "server-user-1" }))
    expect(mocks.saveMessage).toHaveBeenCalledWith(expect.objectContaining({
      role: "assistant", serverMessageId: "server-assistant-1"
    }))
    const userWrite = mocks.saveMessage.mock.calls.find(([message]) => message.role === "user")?.[0]
    expect(userWrite).toMatchObject({ id: "user-1", serverMessageId: "server-user-1" })
  })

  it("commits the complete existing-history turn in one scoped transaction", async () => {
    const controller = new AbortController()
    const scopeInvalidatedController = new AbortController()

    await expect(saveMessageOnSuccess(payload({
      scopeSignal: controller.signal,
      scopeInvalidatedSignal: scopeInvalidatedController.signal,
      requestScope,
      prompt_id: "prompt-1"
    }) as any)).resolves.toBe("history-1")

    expect(mocks.runTransaction).toHaveBeenCalledWith(
      scopeInvalidatedController.signal,
      expect.any(Function)
    )
    expect(mocks.events).toEqual([
      "transaction:start",
      "save:user",
      "save:assistant",
      "save:model",
      "save:prompt",
      "save:createdAt",
      "transaction:commit"
    ])
  })

  it("commits document session files in the same scoped transaction", async () => {
    const controller = new AbortController()
    const scopeInvalidatedController = new AbortController()
    const sessionFile = { id: "file-1", filename: "notes.txt" }

    await expect(saveMessageOnSuccess(payload({
      scopeSignal: controller.signal,
      scopeInvalidatedSignal: scopeInvalidatedController.signal,
      requestScope,
      sessionFilesToAdd: [sessionFile]
    }) as any)).resolves.toBe("history-1")

    expect(mocks.addFileToSession).toHaveBeenCalledWith(
      "history-1",
      sessionFile
    )
    expect(mocks.events).toEqual([
      "transaction:start",
      "save:user",
      "save:assistant",
      "save:model",
      "save:createdAt",
      "save:file:file-1",
      "transaction:commit"
    ])
  })

  it("defers existing-history metadata for a scoped Compare aggregate", async () => {
    const controller = new AbortController()
    const scopeInvalidatedController = new AbortController()

    await expect(saveMessageOnSuccess(payload({
      scopeSignal: controller.signal,
      scopeInvalidatedSignal: scopeInvalidatedController.signal,
      requestScope,
      prompt_id: "prompt-1",
      deferHistoryMetadata: true
    }) as any)).resolves.toBe("history-1")

    expect(mocks.events).toEqual([
      "transaction:start",
      "save:user",
      "save:assistant",
      "transaction:commit"
    ])
  })

  it("generates a scoped title before atomically creating a new history", async () => {
    const controller = new AbortController()
    const scopeInvalidatedController = new AbortController()
    const setHistoryId = vi.fn(() => mocks.events.push("setHistoryId"))

    await expect(saveMessageOnSuccess(payload({
      historyId: null,
      setHistoryId,
      scopeSignal: controller.signal,
      scopeInvalidatedSignal: scopeInvalidatedController.signal,
      requestScope
    }) as any)).resolves.toBe("new-history")

    expect(mocks.generateTitle).toHaveBeenCalledWith(
      "model-1",
      "question",
      "question",
      { signal: scopeInvalidatedController.signal, requestScope }
    )
    expect(mocks.events).toEqual([
      "title",
      "transaction:start",
      "saveHistory",
      "save:user",
      "save:assistant",
      "save:model",
      "transaction:commit",
      "pageTitle",
      "setHistoryId"
    ])
  })

  it("finishes a new history when Stop is pressed during post-success title generation", async () => {
    const controller = new AbortController()
    const scopeInvalidatedController = new AbortController()
    let titleStarted!: () => void
    let finishTitle!: () => void
    const started = new Promise<void>((resolve) => {
      titleStarted = resolve
    })
    const titleGate = new Promise<void>((resolve) => {
      finishTitle = resolve
    })
    mocks.generateTitle.mockImplementationOnce(async (
      _model: string,
      _message: string,
      _question: string,
      options?: { signal?: AbortSignal }
    ) => {
      titleStarted()
      await new Promise<void>((resolve, reject) => {
        options?.signal?.addEventListener("abort", () => {
          const error = new Error("Request cancelled")
          error.name = "AbortError"
          reject(error)
        }, { once: true })
        void titleGate.then(resolve)
      })
      return "Generated title"
    })

    const persistence = saveMessageOnSuccess(payload({
      historyId: null,
      scopeSignal: controller.signal,
      scopeInvalidatedSignal: scopeInvalidatedController.signal,
      requestScope
    }) as any)

    await started
    controller.abort()
    finishTitle()

    await expect(persistence).resolves.toBe("new-history")
    expect(mocks.generateTitle).toHaveBeenCalledWith(
      "model-1",
      "question",
      "question",
      { signal: scopeInvalidatedController.signal, requestScope }
    )
    expect(mocks.saveHistory).toHaveBeenCalledOnce()
    expect(mocks.saveMessage).toHaveBeenCalledTimes(2)
  })

  it("writes nothing for an already-aborted request scope", async () => {
    const controller = new AbortController()
    controller.abort()

    await expect(saveMessageOnSuccess(payload({
      historyId: null,
      scopeSignal: controller.signal,
      scopeInvalidatedSignal: controller.signal,
      requestScope
    }) as any)).rejects.toMatchObject({ name: "AbortError" })

    expect(mocks.generateTitle).not.toHaveBeenCalled()
    expect(mocks.saveHistory).not.toHaveBeenCalled()
    expect(mocks.saveMessage).not.toHaveBeenCalled()
  })
})

// @vitest-environment jsdom
import { beforeEach, describe, expect, it, vi } from "vitest"
import type { SaveMessageData } from "@/types/chat-modes"

const mocks = vi.hoisted(() => ({
  pageAssistModel: vi.fn(),
  getModelNicknameByID: vi.fn(async (_modelId?: unknown) => null),
  saveMessageOnSuccess: vi.fn<(data: SaveMessageData) => Promise<string | null>>(async () => "history-1"),
  saveMessageOnError: vi.fn(async () => "history-1"),
  setMessages: vi.fn(),
  setHistory: vi.fn(),
  setIsProcessing: vi.fn(),
  setStreaming: vi.fn(),
  setAbortController: vi.fn(),
  setHistoryId: vi.fn()
}))

vi.mock("@/models", () => ({
  pageAssistModel: (...args: unknown[]) => mocks.pageAssistModel(...args)
}))

vi.mock("@/db/dexie/helpers", () => ({
  generateID: vi.fn(() => "generated-assistant-id")
}))

vi.mock("@/db/dexie/nickname", () => ({
  getModelNicknameByID: (modelId: unknown) =>
    mocks.getModelNicknameByID(modelId)
}))

vi.mock("@/utils/mcp-disclosure", () => ({
  applyMcpModuleDisclosureFromToolCalls: vi.fn()
}))

vi.mock("@/store/option", () => ({
  useStoreMessageOption: {
    getState: () => ({
      setHistory: vi.fn()
    })
  }
}))

import { runChatPipeline, type ChatModeDefinition, type ChatModeParamsBase } from "../chatModePipeline"
import { decodeChatErrorPayload } from "@/utils/chat-error-message"
import type { Message } from "@/store/option"

describe("runChatPipeline conversation id handoff", () => {
  beforeEach(() => {
    vi.clearAllMocks()
    mocks.setMessages.mockReset()
    mocks.pageAssistModel.mockResolvedValue({
      conversationId: "server-chat-1",
      saveToDb: true,
      stream: async function* () {
        yield "Search-backed answer"
      }
    })
  })

  it.each([
    { acknowledgement: "server-assistant-1", expected: "server-assistant-1" },
    { acknowledgement: undefined, expected: undefined }
  ])("exposes the saved assistant identity only when acknowledged ($acknowledgement)", async ({ acknowledgement, expected }) => {
    mocks.pageAssistModel.mockResolvedValue({
      conversationId: "server-chat-1",
      saveToDb: true,
      serverMessageId: acknowledgement,
      stream: async function* () { yield "Saved reply" }
    })
    let localMessages: Message[] = [{
      id: "generated-assistant-id", isBot: true, name: "Assistant", message: "", sources: []
    }]
    mocks.setMessages.mockImplementation((next: Message[] | ((prev: Message[]) => Message[])) => {
      localMessages = typeof next === "function" ? next(localMessages) : next
    })
    const mode: ChatModeDefinition<ChatModeParamsBase> = {
      id: "normal",
      setupMessages: () => ({ targetMessageId: "generated-assistant-id" }),
      preparePrompt: async () => ({
        chatHistory: [], humanMessage: { role: "user", content: "Hello" }, sources: []
      })
    }

    await runChatPipeline(mode, "Hello", "", false, localMessages, [], new AbortController().signal, {
      selectedModel: "openai/gpt-4.1-mini", useOCR: false,
      setMessages: mocks.setMessages, saveMessageOnSuccess: mocks.saveMessageOnSuccess,
      saveMessageOnError: mocks.saveMessageOnError, setHistory: mocks.setHistory,
      setIsProcessing: mocks.setIsProcessing, setStreaming: mocks.setStreaming,
      setAbortController: mocks.setAbortController, historyId: "history-1",
      setHistoryId: mocks.setHistoryId, conversationId: "server-chat-1"
    })

    expect(localMessages[0].message).toBe("Saved reply")
    expect(localMessages[0].serverMessageId).toBe(expected)
    expect(mocks.saveMessageOnSuccess.mock.calls[0]?.[0]?.assistantServerMessageId).toBe(expected)
  })

  it("retains the acknowledged user when a saved stream fails after persistence", async () => {
    mocks.pageAssistModel.mockResolvedValue({
      conversationId: "server-chat-1", saveToDb: true, userServerMessageId: "server-user",
      stream: async function* () { yield "Partial"; throw new Error("provider failed") }
    })
    let localMessages: Message[] = [
      { id: "local-user", isBot: false, name: "You", message: "Hello" },
      { id: "generated-assistant-id", isBot: true, name: "Assistant", message: "" }
    ]
    mocks.setMessages.mockImplementation(next => {
      localMessages = typeof next === "function" ? next(localMessages) : next
    })
    const mode: ChatModeDefinition<ChatModeParamsBase> = {
      id: "normal", setupMessages: () => ({ targetMessageId: "generated-assistant-id" }),
      preparePrompt: async () => ({ chatHistory: [], humanMessage: { role: "user", content: "Hello" }, sources: [] })
    }
    await runChatPipeline(mode, "Hello", "", false, localMessages, [], new AbortController().signal, {
      selectedModel: "test", useOCR: false, userMessageId: "local-user",
      setMessages: mocks.setMessages, saveMessageOnSuccess: mocks.saveMessageOnSuccess,
      saveMessageOnError: mocks.saveMessageOnError, setHistory: mocks.setHistory,
      setIsProcessing: mocks.setIsProcessing, setStreaming: mocks.setStreaming,
      setAbortController: mocks.setAbortController, historyId: "history-1", setHistoryId: mocks.setHistoryId
    })
    expect(localMessages[0]).toMatchObject({ id: "local-user", serverMessageId: "server-user" })
    expect(mocks.saveMessageOnError).toHaveBeenCalledWith(expect.objectContaining({ userMessageId: "local-user", userServerMessageId: "server-user" }))
    expect(mocks.saveMessageOnSuccess).not.toHaveBeenCalled()
  })

  it("passes explicit conversation ids into pageAssistModel instead of relying on store fallback", async () => {
    const mode: ChatModeDefinition<any> = {
      id: "normal",
      setupMessages: () => ({
        targetMessageId: "generated-assistant-id"
      }),
      preparePrompt: async () => ({
        chatHistory: [{ role: "system", content: "system context" }],
        humanMessage: { role: "user", content: "Hello" },
        sources: []
      })
    }

    await runChatPipeline(
      mode,
      "Hello",
      "",
      false,
      [],
      [],
      new AbortController().signal,
      {
        selectedModel: "openai/gpt-4.1-mini",
        useOCR: false,
        toolChoice: "none",
        setMessages: mocks.setMessages,
        saveMessageOnSuccess: mocks.saveMessageOnSuccess,
        saveMessageOnError: mocks.saveMessageOnError,
        setHistory: mocks.setHistory,
        setIsProcessing: mocks.setIsProcessing,
        setStreaming: mocks.setStreaming,
        setAbortController: mocks.setAbortController,
        historyId: "history-1",
        setHistoryId: mocks.setHistoryId,
        conversationId: "server-chat-1"
      }
    )

    expect(mocks.pageAssistModel).toHaveBeenCalledWith(
      expect.objectContaining({
        model: "openai/gpt-4.1-mini",
        toolChoice: "none",
        conversationId: "server-chat-1"
      })
    )
  })

  it("treats empty model streams as failed recoverable assistant turns", async () => {
    mocks.pageAssistModel.mockResolvedValue({
      conversationId: "server-chat-1",
      saveToDb: true,
      stream: async function* () {}
    })
    let localMessages: any[] = [
      {
        id: "assistant-empty",
        isBot: true,
        name: "Assistant",
        message: "",
        sources: []
      }
    ]
    mocks.setMessages.mockImplementation((next: any[] | ((prev: any[]) => any[])) => {
      localMessages =
        typeof next === "function"
          ? next(localMessages)
          : next
    })

    const mode: ChatModeDefinition<any> = {
      id: "normal",
      setupMessages: () => ({
        targetMessageId: "assistant-empty"
      }),
      preparePrompt: async () => ({
        chatHistory: [{ role: "system", content: "system context" }],
        humanMessage: { role: "user", content: "Hello" },
        sources: []
      })
    }

    const result = await runChatPipeline(
      mode,
      "Hello",
      "",
      false,
      localMessages,
      [],
      new AbortController().signal,
      {
        selectedModel: "openai/gpt-4.1-mini",
        useOCR: false,
        toolChoice: "none",
        setMessages: mocks.setMessages,
        saveMessageOnSuccess: mocks.saveMessageOnSuccess,
        saveMessageOnError: mocks.saveMessageOnError,
        setHistory: mocks.setHistory,
        setIsProcessing: mocks.setIsProcessing,
        setStreaming: mocks.setStreaming,
        setAbortController: mocks.setAbortController,
        historyId: "history-1",
        setHistoryId: mocks.setHistoryId,
        conversationId: "server-chat-1"
      }
    )

    expect(result).toEqual({
      status: "failed",
      errorMessage: "No response text was returned."
    })
    expect(mocks.saveMessageOnSuccess).not.toHaveBeenCalled()
    expect(mocks.saveMessageOnError).toHaveBeenCalledTimes(1)
    expect(localMessages[0].message).toContain("__tldw_error__:")
    expect(decodeChatErrorPayload(localMessages[0].message)?.detail).toBe(
      "No response text was returned."
    )
    expect(localMessages[0].generationInfo).toMatchObject({
      interrupted: true,
      interruptionReason: "No response text was returned."
    })
  })
})

